 "content": "def transform(grid):
    """Restore cells covered by 2 using the grid's dihedral symmetry."""
    h, w = len(grid), len(grid[0])
    if h != w:
        raise ValueError("expected a square grid")
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    n = h
    for r in range(n):
        for c in range(n):
            if src[r][c] != 2:
                continue
            orbit = {
                (r, c), (r, n - 1 - c), (n - 1 - r, c),
                (n - 1 - r, n - 1 - c), (c, r),
                (n - 1 - c, n - 1 - r), (c, n - 1 - r),
                (n - 1 - c, r),
            }
            candidates = [src[a][b] for a, b in orbit if src[a][b] != 2]
            if not candidates:
                raise ValueError(f"no unmasked symmetric source for {(r, c)}")
            # Symmetric counterparts agree in these patterned grids; most
            # common is robust to any accidental inconsistency.
            out[r][c] = max(set(candidates), key=candidates.count)
    return out
